SELECT /*selectMasterWmGrVmiWarhsngList*/ MAX(DECODE(RECV_FLAG,'A','권고발주','B','입고예정','C','센터입고')) AS STATUS , MAX(RD_DATE) RD_DATE, COUNT(VPO_SEQ) VPO_SEQ, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = EDI.BUYER)) ||' ' ||MAX((SELECT USER_NAME_LOC||' ('||PHONE_NUMBER||')' FROM ICOMLUSR WHERE USER_ID = EDI.POK_USER_ID)) AS USER_NAME_LOC, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = EDI.AGENT)) ||' (' ||MAX((SELECT TEL_NO FROM ICOMCMPY WHERE COM_CODE = EDI.AGENT)) ||')' AS COM_NAME_LOC, MAX(VPO_DATE) AS VPO_DATE, VPO_NO AS VPO_NO, MAX(VIV_DATE) AS VIV_DATE , SUM(ITEM_AMT) AS ITEM_AMT, MAX(AGENT) AS AGENT, BUYER, MAX(RECV_FLAG) AS RECV_FLAG, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = EDI.BUYER)) AS BUYER_NAME, MAX((SELECT TEL_NO FROM ICOMCMPY WHERE COM_CODE = EDI.AGENT)) AS AGENT_TEL FROM EDIVPODT EDI
BUYER = #{st_warehouse_code} AND RECV_FLAG ^= 'C' AND STATUS ^= 'D' AND TO_CHAR(TO_DATE(VPO_DATE,'YYYYMMDD')+2,'YYYYMMDD') BETWEEN #{st_from_date} AND #{st_to_date}
AND VPO_NO LIKE '%'|| #{st_po_no} ||'%'
AND VPO_NO LIKE '%'|| #{st_iv_no}||'%'
AND AGENT = #{st_agent_code}
AND RECV_FLAG = #{st_status_check}
GROUP BY BUYER,VPO_NO

mapper.update:

		           UPDATE  WMSSTCK					
                          SET TOT_QTY = TOT_QTY+${ITEM_QTY},		
                                 AVAIL_QTY = AVAIL_QTY+${ITEM_QTY},	 
                                 PRE_GR_QTY = PRE_GR_QTY-(${ITEM_QTY}),	
                               	LAST_REC_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'), 
                               	STC_SELLER_PRICE = ${UNIT_PRICE},		 
                               	LAST_AGENT = #{AGENT}			
                            WHERE WAREHOUSE_CODE = #{BUYER}	
                                 AND STDCATLG_ID =#{BUYER_ITEM_NO}			
                                 AND AGENT = #{AGENT}
